ONLY = [p for p in os.environ.get("MUTANTS_ONLY", "").split(",") if p]
if ONLY:
    M = {k: v for k, v in M.items() if any(k.startswith(p + " ") for p in ONLY)}
SUMMARY = re.compile(r"^\s*\d+ pass\s*$", re.M), re.compile(r"^\s*(\d+) fail\s*$", re.M)


def run(source):
    """('CAUGHT' | 'SURVIVED' | 'RUNNER-FAILED', detail) for one run of the tests against this meshy.js."""
    tmp = tempfile.mkdtemp(prefix="meshy-mod-mut-")
    try:
        dst = os.path.join(tmp, "meshy-mod")
        shutil.copytree(HERE, dst, ignore=shutil.ignore_patterns("mutants.py", "__pycache__"))
        with open(os.path.join(dst, "hooks", "meshy.js"), "w", encoding="utf-8", newline="") as f:
            f.write(source)
        try:
            r = subprocess.run("claude plugin test", cwd=dst, shell=True, capture_output=True, text=True,
                               encoding="utf-8", errors="replace", timeout=300)
        except subprocess.TimeoutExpired:
            return "RUNNER-FAILED", "timed out after 300 s"
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    out = r.stdout or ""
    fails = SUMMARY[1].search(out)
    if not SUMMARY[0].search(out) or not fails or r.returncode not in (0, 1):
        return "RUNNER-FAILED", "exit %s, no pass/fail summary: %s" % (r.returncode, (out + (r.stderr or ""))[-160:].strip())
    failed = [l.strip() for l in out.splitlines() if l.strip().startswith("(fail)")]
    if r.returncode == 1 and int(fails.group(1)) > 0 and failed:
        return "CAUGHT", "; ".join(failed)[:200]
    return "SURVIVED", out[-200:]


tally = {"CAUGHT": 0, "SURVIVED": 0, "RUNNER-FAILED": 0}
for name, (a, b) in M.items():
    assert SRC.count(a) == 1, (name, SRC.count(a))
    for attempt in range(3):
        verdict, detail = run(SRC.replace(a, b))
        if verdict != "RUNNER-FAILED":
            break
    tally[verdict] += 1
    print(name, "|", verdict, "|", detail)
print("caught %d of %d; survived %d; runner failed %d" % (tally["CAUGHT"], len(M), tally["SURVIVED"], tally["RUNNER-FAILED"]))
sys.exit(0 if tally["CAUGHT"] == len(M) else 1)
